const pages=[['Portada','index.html'],['Emprendedores','preview-negocios.html'],['SERVICIOS','servicios.html'],['GASTRONOMÍA','gastronomia.html'],['PROMOCIONES','preview-promociones.html'],['Club Montevideo · Demo','club-montevideo.html'],['Dúos Montevideo','preview-duos.html'],['Inmobiliarias','inmobiliarias.html'],['El barrio','preview-barrio.html'],['Sumá tu negocio','solicitar-espacio.html']];if(location.pathname==='/'||location.pathname.endsWith('/index.html'))pages.splice(0,pages.length,...[['Portada','index.html'],['Emprendedores','preview-negocios.html'],['SERVICIOS','servicios.html'],['GASTRONOMÍA','gastronomia.html'],['PROMOCIONES','preview-promociones.html'],['Club Montevideo · Demo','club-montevideo.html'],['Dúos Montevideo','preview-duos.html'],['Inmobiliarias','inmobiliarias.html'],['Cocina','preview-cocina.html'],['El barrio','preview-barrio.html'],['Publicá tu negocio','publica-tu-negocio.html']]);const nav=document.querySelector('#nav');if(nav){nav.innerHTML=pages.map(([label,href])=>`<a href="/${href}" ${location.pathname.endsWith(href)?'class="active"':''}>${label}</a>`).join('')}

if(nav){nav.setAttribute("aria-label","Navegación principal");const style=document.createElement("style");style.textContent=`#nav{background:#171717!important;display:flex;flex-wrap:wrap;gap:6px 12px!important;overflow:visible!important;white-space:normal!important;padding:12px 22px!important}#nav a,#nav a:visited{color:#fff!important;text-decoration:none;font:700 14px/1.4 Arial,Helvetica,sans-serif;padding:10px 12px;border-radius:6px;display:inline-flex;align-items:center;min-height:40px}#nav a:hover,#nav a.active{background:#393939!important;color:#fff!important}#nav a:focus-visible{outline:2px solid #fff;outline-offset:2px}@media(max-width:600px){#nav{gap:4px!important;padding:10px 12px!important}#nav a{font-size:13px;padding:9px 10px}}`;document.head.append(style);}
